  1910	/**
  1911	 * A granted worker that has not published provider identity is neither safe to
  1912	 * signal by bare PID nor safe to wait on forever. Give cancellation a bounded
  1913	 * cooperative window, then seal an explicitly replacement-unsafe terminal so
  1914	 * recovery cannot mistake an unobserved child for a reaped provider.
  1915	 */
  1916	const MANAGED_HOST_RUN_PREIDENTITY_RECOVERY_GRACE_MS = 500;
