  1922	/**
  1923	 * A present leader must still be the process we spawned. If it has exited but
  1924	 * the observed PGID still has members, that group cannot have been recycled:
  1925	 * POSIX cannot allocate the PGID to another group until its last member exits.
  1926	 * This narrowly permits reaping a leaderless descendant tree while continuing
  1927	 * to fail closed if the numeric leader PID has been reused.
  1928	 */
  1929	function canSignalObservedManagedProviderGroup(
  1930	  identity: HostRunProcessIdentity,
  1931	  rows: ManagedHostRunProcessGroupRow[],
  1932	): boolean {
  1933	  if (!isSafeIsolatedProviderProcessGroup(identity)) return false;
  1934	  const leader = rows.find(row => row.pid === identity.pid);
  1935	  return leader === undefined || leader.start === identity.startFingerprint;
  1936	}
