  1938	export async function reapManagedHostRunProviderProcess(
  1939	  identity: HostRunProcessIdentity | null,
  1940	  ops: ManagedHostRunProcessGroupOps = DEFAULT_PROCESS_GROUP_OPS,
  1941	): Promise<HostRunProcessCleanup> {
  1942	  if (!isSafeIsolatedProviderProcessGroup(identity)) {
  1943	    return AMBIGUOUS_PROCESS_CLEANUP;
  1944	  }
  1945	  let rows = ops.rows(identity.pgid);
  1946	  if (rows === null) return AMBIGUOUS_PROCESS_CLEANUP;
  1947	  if (rows.length === 0) return REAPED_WITHOUT_SIGNAL;
  1948	  if (!canSignalObservedManagedProviderGroup(identity, rows)) return AMBIGUOUS_PROCESS_CLEANUP;
  1949	
  1950	  let termSent = false;
  1951	  try {
  1952	    ops.signal(identity.pgid, 'SIGTERM');
  1953	    termSent = true;
  1954	  } catch (error) {
  1955	    if ((error as NodeJS.ErrnoException).code !== 'ESRCH') return AMBIGUOUS_PROCESS_CLEANUP;
  1956	  }
  1957	  await ops.wait(250);
  1958	  rows = ops.rows(identity.pgid);
  1959	  if (rows === null) return { termSent, killSent: false, reaped: false, residualProcessGroup: true };
  1960	  if (rows.length === 0) return { termSent, killSent: false, reaped: true, residualProcessGroup: false };
  1961	  if (!canSignalObservedManagedProviderGroup(identity, rows)) {
  1962	    return { termSent, killSent: false, reaped: false, residualProcessGroup: true };
  1963	  }
  1964	  let killSent = false;
  1965	  try {
  1966	    ops.signal(identity.pgid, 'SIGKILL');
  1967	    killSent = true;
  1968	  } catch (error) {
  1969	    if ((error as NodeJS.ErrnoException).code !== 'ESRCH') {
  1970	      return { termSent, killSent, reaped: false, residualProcessGroup: true };
  1971	    }
  1972	  }
  1973	  await ops.wait(250);
  1974	  rows = ops.rows(identity.pgid);
  1975	  const reaped = rows !== null && rows.length === 0;
  1976	  return { termSent, killSent, reaped, residualProcessGroup: !reaped };
  1977	}
