  2001	    // worker cannot hold the status API forever: after the grace, the next touch
  2002	    // reconciles against the recorded provider identity and writes an honest
  2003	    // terminal even when replacement safety cannot be proven.
  2004	    if (now - Date.parse(request.requestedAt) < 250) return;
  2005	    const launchState = fenceLaunchBeforeTerminal();
  2006	    const fencedSnapshot = readJson<ManagedHostRunSnapshot>(paths.snapshot);
  2007	    // The worker can be between its durable launch grant and provider identity
  2008	    // publication. Bare worker PIDs are not safe authority (they can be reused),
  2009	    // so never signal one here. A live worker gets a bounded cooperative window;
  2010	    // after it expires the ambiguous cleanup terminal records residual risk
  2011	    // rather than leaving status polling wedged forever.
