  2089	  const baseline = typeof args.afterGeneration === 'number' ? args.afterGeneration : run.generation;
  2090	  const now = args.now ?? Date.now;
  2091	  const deadline = now() + waitMs;
  2092	  while (true) {
  2093	    await reconcileManagedHostRun(paths, now(), args.processGroupOps);
  2094	    run = projectionFor(paths);
