  2096	    if (changed || now() >= deadline || waitMs === 0) {
  2097	      return {
  2098	        schemaVersion: MANAGED_HOST_RUN_SCHEMA_VERSION,
  2099	        changed,
  2100	        run,
  2101	        receipt: run.terminal ? managedHostRunReceipt(args.root, args.runId) : null,
  2102	      };
  2103	    }
  2104	    await sleep(Math.min(50, Math.max(1, deadline - now())));
  2105	  }
  2106	}
